const mexicoTreasureData=[{"name":"Chichén Itzá","subtitle":"Ancient wonder","description":"An ancient Maya city celebrated for the stepped Temple of Kukulcán and its remarkable ceremonial monuments.","region":"Mexico, Yucatán","lat":20.6843,"lon":-88.5678},{"name":"El Arco","subtitle":"Sea & stone","description":"A natural granite arch rising from the sea at Land’s End, the dramatic southern tip of the Baja California peninsula.","region":"Mexico, Baja California Sur","lat":22.876,"lon":-109.8947},{"name":"Zócalo","subtitle":"Historic Mexico City","description":"Mexico City’s grand central plaza, framed by the Metropolitan Cathedral and National Palace in the historic centre.","region":"Mexico, Mexico City","lat":19.4326,"lon":-99.1332}];
const mexicoTreasureIcons=["<svg viewBox=\"0 0 100 100\" aria-hidden=\"true\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M19 73h62L70 65H30zM27 64h46l-7-9H34zM34 54h32l-5-9H39zM40 44h20V33H40zM44 33V23h12v10M47 73V43h6v30M43 23h14\"/><path d=\"M49 48h2m-2 5h2m-2 5h2m-2 5h2m-2 5h2\"/><path d=\"M13 79h74M18 21l3 4m-6 4h5m57-8-3 4m8 4h-5\"/></svg>","<svg viewBox=\"0 0 100 100\" aria-hidden=\"true\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M13 70l5-27 12-15 11 4 9 10 11-3 9-17 13 9 4 39H66l-4-17-7-7-8 1-8 10-3 13z\"/><path d=\"M20 62l6-18 9-8m38-3 6 8 3 20M14 77q8-5 16 0t16 0 16 0 16 0 10 0M19 85q8-5 16 0t16 0 16 0 14 0\"/><circle cx=\"51\" cy=\"21\" r=\"7\"/></svg>","<svg viewBox=\"0 0 100 100\" aria-hidden=\"true\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M15 70V37h14v33m42 0V37h14v33M13 37h18l-4-9h-10zM69 37h18l-4-9H73zM20 28V18m58 10V18M17 21h6m52 0h6M31 70V48l19-15 19 15v22M44 70V56a6 6 0 0 1 12 0v14M29 72h42M36 48h28\"/><circle cx=\"50\" cy=\"45\" r=\"3\"/><path d=\"M21 43v6m0 6v6m57-18v6m0 6v6M11 78h78M17 86l16-8m50 8-16-8M50 78v10\"/></svg>"];
function countryTreasures(key){if(key!=='mexico')return '';return '<section class="mexico-treasures" aria-label="Mexico treasures"><p class="treasures-label treasure-reward-line"><span>TREASURES OF MEXICO - collect all 3 to get sombrero on your profile</span><svg class="sombrero-outline" viewBox="0 0 64 40" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M19 24c3-7 4-19 13-19s10 12 13 19M19 24q13 7 26 0M21 20q11 5 22 0M19 22C8 22 3 25 3 29c0 5 13 8 29 8s29-3 29-8c0-4-5-7-16-7M7 29q25 9 50 0"/></svg></p><div class="treasure-badges">'+mexicoTreasureData.map((t,i)=>'<button type="button" class="treasure-badge" data-treasure="'+i+'" aria-label="Discover '+t.name+'" aria-pressed="false">'+mexicoTreasureIcons[i]+'<span class="treasure-caption"><strong>'+t.name+'</strong><span>'+t.subtitle+'</span></span></button>').join('')+'</div><div class="treasure-inline-details" hidden role="region" aria-label="Selected treasure details" aria-live="polite"></div></section>';}

function clearTreasureDetails(){const panel=document.querySelector('.treasure-inline-details');if(panel){panel.hidden=true;panel.replaceChildren();}document.querySelectorAll('[data-treasure]').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false');});}
function setupTreasureDetails(){document.querySelectorAll('[data-treasure]').forEach(button=>button.onclick=()=>{
 document.querySelectorAll('[data-treasure]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button));});
 const t=mexicoTreasureData[Number(button.dataset.treasure)],panel=document.querySelector('.treasure-inline-details');
 panel.innerHTML='<h3>'+t.name+'</h3><p>'+t.description+'</p><p class="treasure-region">'+t.region+'</p><a class="treasure-map-link" href="https://www.google.com/maps/search/?api=1&amp;query='+t.lat+','+t.lon+'" target="_blank" rel="noopener noreferrer">Latitude '+t.lat.toFixed(4)+'° · Longitude '+t.lon.toFixed(4)+'° ↗ Google Maps</a>';panel.hidden=false;
});}
document.addEventListener('click',event=>{if(event.target.closest('[data-treasure]'))return;const link=event.target.closest('.treasure-map-link');if(link){setTimeout(clearTreasureDetails,0);return;}clearTreasureDetails();});
document.addEventListener('keydown',event=>{if(event.key==='Escape')clearTreasureDetails();});
